scwin.vScrenID = "ULDINS15300.xml";
scwin.cnt = 0;

// 수정전 발행일
scwin.pre_ISU_DD = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 주식워런트(ELW) 표준코드관리  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    /**
     * SrM-000243255 
     */
    if (!scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pISU_DD_SDATE, edt_pISU_DD_EDATE) == false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
        return false;
    }

    //데이터셋 초기화
    dts_List.removeAll();
    dts_detail.removeAll();
    //set_Change();

    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    // 조회버튼 비활성.
    fn_SetDisableSelectBtn(btn_search, true);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS15700_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdElwInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}ISU_NM=" + txb_pISU_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ISU_DD_SDATE=" + edt_pISU_DD_SDATE.getValue() + "&{P}ISU_DD_EDATE=" + edt_pISU_DD_EDATE.getValue() + "&{P}STD_CD_GRNT_DD_SDATE=" + edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "&{P}STD_CD_GRNT_DD_EDATE=" + edt_pSTD_CD_GRNT_DD_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : checkSearchCondition
 * 설명      : SrM-000243255  조회조건을 체크
 *                표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 
 *                날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..
 ***********************************************/
scwin.checkSearchCondition = function() {
    var sStdCd = $c.stf.getObjectValue(txb_pSTD_CD);
    var sIsuKorNm = $c.stf.getObjectValue(txb_pISU_NM);
    var sIsurCd = $c.stf.getObjectValue(txb_pISUR_CD);
    var sIsuDateFrom = $c.stf.getObjectValue(edt_pISU_DD_SDATE); //발행일(from)
    var sIsuDateTo = $c.stf.getObjectValue(edt_pISU_DD_EDATE); //발행일(to)
    var sSDateFrom = $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE); //코드부여일(from)
    var sSDateTo = $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE); //코드부여일(to)

    if (sStdCd == "" && sIsuKorNm == "" && sIsurCd == "") {
        if (sIsuDateFrom == "" && sIsuDateTo == "" && sSDateFrom == "" && sSDateTo == "") {
            var msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명, 발행기관명(코드)] 중 1개 이상의 조건을 입력하거나, \n" + "[발행일 또는 코드부여일]의 검색기간을 5년 이내로 입력하세요.";
            $c.win.alert(msg);
            return false;
        }

        // 발행일 체크
        if (sIsuDateFrom != "" && sIsuDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sIsuDateFrom, 5)) < eval(sIsuDateTo)) {
                $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
                edt_pISU_DD_SDATE.focus();
                return false;
            }
        } else if (sIsuDateFrom != "" || sIsuDateTo != "") {
            $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
            if (sIsuDateFrom == "") {
                edt_pISU_DD_SDATE.focus();
            } else {
                edt_pISU_DD_EDATE.focus();
            }
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom != "" && sSDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sSDateFrom, 5)) < eval(sSDateTo)) {
                $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom != "" || sSDateTo != "") {
            $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
            if (sSDateFrom == "") {
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
            } else {
                edt_pSTD_CD_GRNT_DD_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 주식워런트(ELW) 표준코드관리 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    //데이터셋 초기화
    dts_detail.removeAll();
    //set_Change();

    // 수익증권 표준코드관리
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS15300_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.readStdCdElwInfoView" + "&{P}STD_CD=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};



/********************************************** 
 * 함수명   : ins_process	
 * 설명       : 주식워런트(ELW) 표준코드관리 저장 , 수정 한다. screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_modify = function(flag) {
    var screenProcsTpCd = "03";
    if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_detail)) {
            $c.win.alert("변경된 데이터가 없습니다.");
