        }
        if (txb_ISUR_CD.getValue() == "" || txb_ISUR_CD.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
            txb_ISUR_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_WRNT_ISUR_CD).length != "2") {
            $c.win.alert("워런트발행기관코드를 확인해 주십시오");
            return false;
        }
        if (txb_STD_CD.getValue() == "" || txb_STD_CD.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "표준코드"));
            txb_STD_CD.focus();
            return false;
        }
        if (txb_ISU_SRT_CD.getValue() == "" || txb_ISU_SRT_CD.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "단축코드"));
            txb_ISU_SRT_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
            txb_ISU_NM.focus();
            return false;
        }
        if (txb_ISU_ABBRV1.getValue() == "" || txb_ISU_ABBRV1.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_1(한글)"));
            txb_ISU_ABBRV1.focus();
            return false;
        }
        if (txb_ISU_ABBRV2.getValue() == "" || txb_ISU_ABBRV2.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_2(한글)"));
            txb_ISU_ABBRV2.focus();
            return false;
        }
        if (txb_ISU_ABBRV3.getValue() == "" || txb_ISU_ABBRV3.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_3(한글)"));
            txb_ISU_ABBRV3.focus();
            return false;
        }
        if (txb_ISU_ABBRV4.getValue() == "" || txb_ISU_ABBRV4.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_4(한글)"));
            txb_ISU_ABBRV4.focus();
            return false;
        }
        if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV1.getValue() == "" || txb_ISU_ENG_ABBRV1.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_1(영문)"));
            txb_ISU_ENG_ABBRV1.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV2.getValue() == "" || txb_ISU_ENG_ABBRV2.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_2(영문)"));
            txb_ISU_ENG_ABBRV2.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV3.getValue() == "" || txb_ISU_ENG_ABBRV3.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_3(영문)"));
            txb_ISU_ENG_ABBRV3.focus();
            return false;
        }
        if (txb_ISU_ENG_ABBRV4.getValue() == "" || txb_ISU_ENG_ABBRV4.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "종목약명_4(영문)"));
            txb_ISU_ENG_ABBRV4.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
            txb_ISU_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV1, 20, "종목약명_1(한글)")) {
            txb_ISU_ABBRV1.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV2, 20, "종목약명_2(한글)")) {
            txb_ISU_ABBRV2.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV3, 20, "종목약명_3(한글)")) {
            txb_ISU_ABBRV3.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ABBRV4, 20, "종목약명_4(한글)")) {
            txb_ISU_ABBRV4.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
            txb_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV1, 20, "종목약명_1(영문)")) {
            txb_ISU_ENG_ABBRV1.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV2, 20, "종목약명_2(영문)")) {
            txb_ISU_ENG_ABBRV2.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV3, 20, "종목약명_3(영문)")) {
            txb_ISU_ENG_ABBRV3.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV4, 20, "종목약명_4(영문)")) {
            txb_ISU_ENG_ABBRV4.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ISU_DD) == "" || $c.stf.getObjectValue(edt_ISU_DD).length != "8") {
            $c.win.alert("발행일을 확인해 주십시오");
            edt_ISU_DD.focus();
            return false;
        }
        if (scwin.pre_ISU_DD != undefined && scwin.pre_ISU_DD.length == 8) {
            if ($c.stf.getObjectValue(edt_ISU_DD).substring(0, 6) != scwin.pre_ISU_DD.substring(0, 6)) {
                $c.win.alert("표준코드의 속성코드인 발행년, 발행월의 숫자는 수정할 수 없습니다");
                edt_ISU_DD.focus();
                $c.stf.setObjectValue(edt_ISU_DD, scwin.pre_ISU_DD);
                return false;
            }
        }
        if ($c.stf.getObjectValue(cmb_FNC_ULY_TP_CD) == "") {
            $c.win.alert("금융기초자산구분을 선택하세요");
            cmb_FNC_ULY_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_FNC_ULY_TP_CD) == "1" || $c.stf.getObjectValue(cmb_FNC_ULY_TP_CD) == "2") {
            if ($c.stf.getObjectValue(cmb_ULY_ISU_CD1) == "") {
                $c.win.alert("주권발행기관_1을 선택하세요");
                cmb_ULY_ISU_CD1.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(cmb_FNC_ULY_TP_CD) == "3") {
            if ($c.stf.getObjectValue(cmb_ELW_OBJ_IDX_TP_CD) == "") {
                $c.win.alert("주가지수구분을 선택하세요");
                cmb_ELW_OBJ_IDX_TP_CD.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(cmb_ELW_OBJ_IDX_TP_CD) != "") {
            if ($c.stf.getObjectValue(cmb_ELW_OBJ_IDX_TP_CD) == "1" ||
                $c.stf.getObjectValue(cmb_ELW_OBJ_IDX_TP_CD) == "2" ||
                $c.stf.getObjectValue(cmb_ELW_OBJ_IDX_TP_CD) == "3" ||
                $c.stf.getObjectValue(cmb_ELW_OBJ_IDX_TP_CD) == "4") {
                var strElwObjIdxTpCdText = cmb_ELW_OBJ_IDX_TP_CD.text.split(" ");
                if (strElwObjIdxTpCdText[1] != txb_ISU_ABBRV3.getValue()) {
                    $c.win.alert("주가지수구분과 종목약명3가 다릅니다");
                    txb_ISU_ABBRV3.focus();
                    return false;
                }
                if (strElwObjIdxTpCdText[1] != txb_ISU_ENG_ABBRV3.getValue()) {
                    $c.win.alert("주가지수구분과 영문종목약명3가 다릅니다");
                    txb_ISU_ENG_ABBRV3.focus();
                    return false;
                }
            }
        }

        /*
        if(getObjectValue(cmb_ULY_ISU_CD1) != "" && getObjectValue(edt_ULY_COMPST_RTO1) == ""){
        	edt_ULY_COMPST_RTO1.focus();
        	alert("대상주권_1의 구성주식수를 입력하세요");
        	return false ;
        }

        if(getObjectValue(cmb_ULY_ISU_CD2) != "" && getObjectValue(edt_ULY_COMPST_RTO2) == ""){
        	edt_ULY_COMPST_RTO2.focus();
        	alert("대상주권_2의 구성주식수를 입력하세요");
        	return false ;
        }

        if(getObjectValue(cmb_ULY_ISU_CD3) != "" && getObjectValue(edt_ULY_COMPST_RTO3) == ""){
        	edt_ULY_COMPST_RTO3.focus();
        	alert("대상주권_3의 구성주식수를 입력하세요");
        	return false ;
        }

        if(getObjectValue(cmb_ULY_ISU_CD4) != "" && getObjectValue(edt_ULY_COMPST_RTO4) == ""){
        	edt_ULY_COMPST_RTO4.focus();
        	alert("대상주권_4의 구성주식수를 입력하세요");
        	return false ;
        }

        if(getObjectValue(cmb_ULY_ISU_CD5) != "" && getObjectValue(edt_ULY_COMPST_RTO5) == ""){
        	edt_ULY_COMPST_RTO5.focus();
        	alert("대상주권_5의 구성주식수를 입력하세요");
        	return false ;
        }
        */

        /* 권리유형이 수정불가라 체크 로직 수정 필요 */
        if ($c.stf.getObjectValue(cmb_RGHT_TP_CD) == "") {
            $c.win.alert("권리유형을 선택하세요");
            cmb_RGHT_TP_CD.focus();
            return false;
        }

        //CFI체크
        if ($c.stf.getObjectValue(cmb_cb_p_group) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
            cmb_cb_p_group.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
            cmb_cb_p_attr_1.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
            cmb_cb_p_attr_2.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
            cmb_cb_p_attr_3.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
            cmb_cb_p_attr_4.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
            //txb_ISU_ENG_ABBRV.value = "";
            txa_NUSUAL_ISU_COND_CONTN.focus();
            return false;
        }
        if (flag == "N") return;
        trs_save.Action = "/StdCdElwInfoAction.do?method=modifyStdCdElwInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_detail)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
};




/********************************************** 
 * 함수명   : ins_remove	
 * 설명       : 표준코드 삭제
 ***********************************************/
scwin.ins_remove = function() {
    var screenProcsTpCd = "04";
    //dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD"));
    dts_Delete.setCellData(1, "ISU_NM", dts_detail.getCellData(dts_detail.getRowPosition(), "ISU_NM"));
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
