scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    // 수정시 비교를 위해 수정전발행일을 저장한다
    scwin.pre_ISU_DD = dts_detail.getCellData(dts_detail.rowpositon, "ISU_DD");
    var str_cfi_cd = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");
    //var str_bnd_stkcert_tp_cd = dts_detail.NameValue(dts_detail.rowpositon, "BND_STKCERT_TP_CD");	

    scwin.set_Change(str_cfi_cd);
    var tgt_uly_isu_cd = new Array();
    var uly_isu_cd = new Array();
    var uly_isu_nm = new Array();
    for (var i = 1; i < 6; i++) {
        tgt_uly_isu_cd.push(dts_detail.getCellData(dts_detail.rowpositon, "TGT_ULY_ISU_CD" + i));
        uly_isu_cd.push(dts_detail.getCellData(dts_detail.rowpositon, "ULY_ISU_CD" + i));
        uly_isu_nm.push(dts_detail.getCellData(dts_detail.rowpositon, "ULY_ISU_NM_" + i));
    }
    scwin.fn_SetComboCode(uly_isu_cd, tgt_uly_isu_cd, uly_isu_nm);
    var elw_rght_tp_kind_cd = $c.stf.getObjectValue(cmb_ELW_RGHT_TP_KIND_CD);
    if (elw_rght_tp_kind_cd == "2") {
        edt_LST_PAY_AMT.setReadOnly(false);
        edt_LST_PAY_AMT.ReadOnlyBackColor = 'white';
    } else {
        edt_LST_PAY_AMT.setReadOnly(true);
        edt_LST_PAY_AMT.ReadOnlyBackColor = '#b9d4f7';
    }
    var isu_eng_nm = dts_detail.getCellData(dts_detail.rowpositon, "ISU_ENG_NM");
    if (ISU_ENG_NM.length > 80) {
        isu_eng_nm = ISU_ENG_NM.replace(/ /gi, "");
        $c.stf.setObjectValue(txb_ISU_ENG_NM, isu_eng_nm);
    }
    var isu_nm = dts_detail.getCellData(dts_detail.rowpositon, "ISU_NM");
    if (ISU_NM.length > 80) {
        isu_nm = ISU_NM.replace(/ /gi, "");
        $c.stf.setObjectValue(txb_ISU_NM, isu_nm);
    }
    fn_CtrlBtn_temp("update");
    var lst_yn = dts_detail.getCellData(dts_detail.rowpositon, "LIST_STAT_CD");
    var pre_simsa_pass_yn = dts_detail.getCellData(dts_detail.rowpositon, "PRE_SIMSA_PASS_YN");
    var pre_simsa_reject_yn = dts_detail.getCellData(dts_detail.rowpositon, "PRE_SIMSA_REJECT_YN");
    var simsa_yn = dts_detail.getCellData(dts_detail.rowpositon, "SIMSA_YN");
    var btnflag = false;
    if (lst_yn == "Y") {
        //alert("상장종목은 수정할 수 없습니다. \n증권상품시장부와 협의하시기 바랍니다.");
        btnflag = true;
    } else if (lst_yn == "N" && pre_simsa_pass_yn == "Y") {
        $c.win.alert("심사 [접수] 처리된 종목은 수정 및 삭제할 수 없습니다. \n증권상품시장부와 협의하시기 바랍니다.");
        btnflag = true;
    } else if (lst_yn == "N" && pre_simsa_pass_yn == "N" && pre_simsa_reject_yn == "Y") {
        $c.win.alert("예비심사 [반송] 처리된 종목은 수정 및 삭제할 수 있습니다.");
        btnflag = false;
    } else if (lst_yn == "N" && simsa_yn == "Y") {
        $c.win.alert("신규상장 심사종목은 수정 및 삭제할 수 없습니다. \n증권상품시장부와 협의하시기 바랍니다");
        btnflag = true;
    }
    if (btnflag == true) {
        btn_modify.setDisabled(true);
        btn_modify.src = "../img/ins/btn_modify_d.gif";
        btn_delete.setDisabled(true);
        btn_delete.src = "../img/ins/btn_delete_d.gif";

        // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.src = "../img/ins/btn_clearPwd_d.gif";
    }
};
