    var B = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "B")); // 종목약명1 
    var C = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "C")); // 종목약명2
    var D = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "D")); // 종목약명3
    var E = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "E")); // 종목약명4 
    var F = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "F")); // 영문명
    var G = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "G")); // 영문약명1
    var H = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "H")); // 영문약명2
    var I = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "I")); // 영문약명3
    var J = $c.stf.trim(dts_createStdCdElwStdIsuNm.getCellData(1, "J")); // 영문약명4

    $c.stf.setObjectValue(txb_ISU_NM, A);
    $c.stf.setObjectValue(txb_ISU_ABBRV1, B);
    $c.stf.setObjectValue(txb_ISU_ABBRV2, C);
    $c.stf.setObjectValue(txb_ISU_ABBRV3, D);
    $c.stf.setObjectValue(txb_ISU_ABBRV4, E);
    $c.stf.setObjectValue(txb_ISU_ENG_NM, F);
    $c.stf.setObjectValue(txb_ISU_ENG_ABBRV1, G);
    $c.stf.setObjectValue(txb_ISU_ENG_ABBRV2, H);
    $c.stf.setObjectValue(txb_ISU_ENG_ABBRV3, I);
    $c.stf.setObjectValue(txb_ISU_ENG_ABBRV4, J);
};
